mapper.select:
select id, user_id, user_name, remote_ip, remote_port, remote_browser, remote_os, login_status, update_time, create_time from t_user_login_log
AND DATE_FORMAT(create_time, '%Y-%m-%d') >= #{queryDTO.startDate}
AND DATE_FORMAT(create_time, '%Y-%m-%d') <= #{queryDTO.endDate}
AND INSTR(user_name,#{queryDTO.userName})
order by create_time desc
